'use strict';
const img=['https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Electric_transmission_power_tower.jpg/960px-Electric_transmission_power_tower.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/a/a7/CellTower.jpg/960px-CellTower.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/3/3d/Cell_tower_aerial.jpg/960px-Cell_tower_aerial.jpg'];
const serviceImages=['https://upload.wikimedia.org/wikipedia/commons/c/c0/Electrical_Substation.JPG','https://upload.wikimedia.org/wikipedia/commons/thumb/a/a7/CellTower.jpg/960px-CellTower.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Electric_transmission_power_tower.jpg/960px-Electric_transmission_power_tower.jpg','https://upload.wikimedia.org/wikipedia/commons/thumb/a/ab/Radio_tower_top_close.JPG/960px-Radio_tower_top_close.JPG'];
const originalPhotos=['assets/instalaciones-electricas.svg','assets/montaje-antenas.svg','assets/infraestructura-electrica.svg','assets/radio-bases.svg'];
const fallbackPhotos=['assets/infraestructura-electrica.svg','assets/montaje-antenas.svg','assets/radio-bases.svg'];
const services=[
{id:'electricos',name:'Trabajos eléctricos',detail:'Diseño, instalación y mantenimiento de sistemas eléctricos para instalaciones institucionales e industriales.',points:['Diagnóstico de sistemas eléctricos','Instalación y adecuación técnica','Mantenimiento preventivo y correctivo','Verificación y entrega']},
{id:'antenas',name:'Montaje de antenas',detail:'Instalación técnica de estructuras y antenas con criterios de seguridad, estabilidad y cobertura.',points:['Evaluación del emplazamiento','Montaje de estructuras','Supervisión de seguridad','Inspección de instalación']},
{id:'lineas',name:'Líneas de media tensión',detail:'Tendido y mantenimiento de redes de distribución para proyectos de infraestructura eléctrica.',points:['Evaluación técnica','Planificación de tendido','Ejecución conforme al proyecto','Verificación final']},
{id:'radio',name:'Instalación de radio bases',detail:'Implementación de infraestructura para telecomunicaciones y conectividad.',points:['Evaluación de requerimientos','Montaje de infraestructura','Integración de equipos','Revisión del montaje']}];
const projects=[{id:'red-media-tension',cat:'Eléctrico',title:'Tendido de red de media tensión',place:'Potosí, Bolivia',pic:img[0],detail:'Ejemplo de ficha para presentar infraestructura eléctrica.'},{id:'montaje-antena',cat:'Telecomunicaciones',title:'Montaje de infraestructura de antena',place:'Potosí, Bolivia',pic:img[1],detail:'Ejemplo de ficha para presentar trabajos de telecomunicaciones.'},{id:'radio-base',cat:'Radio bases',title:'Implementación de radio base',place:'Bolivia',pic:img[2],detail:'Ejemplo de ficha para presentar instalación de radio bases.'}];
// Solo completar estos datos después de la autorización del propietario.
const contact={whatsapp:'',email:'',hours:''}; // Completar únicamente con datos oficiales autorizados
const main=document.getElementById('contenido');
const modoSinServidor = location.protocol === 'file:';
const rutaActual = () => (modoSinServidor ? (location.hash.slice(1) || '/') : location.pathname);
function cambiarRuta(ruta) {
 if (modoSinServidor) { if(location.hash !== '#' + ruta) location.hash = ruta; else render(); }
 else { history.pushState({}, '', ruta); render(); }
}
function guardarLocal(data) {
 const items=JSON.parse(localStorage.getItem('ilutex_solicitudes') || '[]');
 items.push({...data, id:'LOCAL-'+Date.now(), recibido:new Date().toISOString()});
 localStorage.setItem('ilutex_solicitudes',JSON.stringify(items));
}
function descargarSolicitudes() {
 const items=JSON.parse(localStorage.getItem('ilutex_solicitudes') || '[]');
 if(!items.length){alert('No hay solicitudes registradas en este navegador.');return;}
 const keys=['id','recibido','tipo','nombre','empresa','correo','telefono','servicio','ubicacion','mensaje','necesidad','inversion'];
 const csv='\uFEFF'+[keys.join(';'),...items.map(item=>keys.map(k=>'"'+String(item[k]||'').replace(/"/g,'""')+'"').join(';'))].join('\r\n');
 const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));link.download='Solicitudes_ILUTEX.csv';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),3000);
}

const page=(eye,title,desc)=>`<section class="pagehero"><div class="wrap"><span class="eyebrow">${eye}</span><h1>${title}</h1><p>${desc}</p></div></section>`;
const a=(href,text,cls='btn')=>`<a class="${cls}" href="${modoSinServidor?'#'+href:href}" data-route>${text}</a>`;
const title=(eye,head,desc='')=>`<div><span class="eyebrow">${eye}</span><h2>${head}</h2>${desc?`<p>${desc}</p>`:''}</div>`;
const serviceCards=()=>`<div class="grid">${services.map((s,i)=>`<a class="card service" href="${modoSinServidor?'#':''}/servicio/${s.id}" data-route><div class="service-visual"><img src="${serviceImages[i]}" onerror="this.onerror=null;this.src='${originalPhotos[i]}'" alt="Fotografía de referencia: ${s.name}" loading="lazy"><span class="service-index">0${i+1}</span></div><div class="service-content"><h3>${s.name}</h3><p>${s.detail}</p><span class="link">Ver detalle ↗</span></div></a>`).join('')}</div>`;
const projectCards=(items=projects)=>`<div class="grid three">${items.map(p=>`<a class="card project" href="${modoSinServidor?'#':''}/proyecto/${p.id}" data-route><img src="${p.pic}" onerror="this.onerror=null;this.src='assets/infraestructura-electrica.svg'" alt="Fotografía de referencia: ${p.title}" loading="lazy"><div><small>${p.cat}</small><h3>${p.title}</h3><p>${p.place} · Ejemplo ilustrativo</p></div></a>`).join('')}</div>`;
const cta=()=>`<section class="highlight"><div class="wrap">${title('¿Tienes un proyecto?','Convirtamos tu requerimiento en una solución técnica.')}${a('/cotizacion','Solicitar cotización ↗')}</div></section>`;
const note='<p class="photo-disclaimer">Fotografías referenciales del sector. No corresponden a obras acreditadas de ILUTEX L.S.; las fichas de proyectos son ejemplos académicos.</p>';
const views={
'/':()=>`<section class="wrap hero"><div><span class="eyebrow">Potosí, Bolivia · Desde 2007</span><h1>Ingeniería eléctrica y <span style="color:var(--green)">telecomunicaciones</span> para proyectos institucionales</h1><p>Trabajos eléctricos, montaje de antenas, líneas de media tensión e instalación de radio bases ejecutados con responsabilidad técnica.</p><div class="actions">${a('/cotizacion','Solicitar cotización ↗')}${a('/nosotros','Conocer la empresa','btn alt')}</div></div><div class="hero-pic"><div class="hero-orbit" aria-hidden="true"></div><img src="${img[0]}" onerror="this.onerror=null;this.src='assets/infraestructura-electrica.svg'" alt="Fotografía de infraestructura eléctrica"><div class="hero-label">Experiencia técnica<br><small>Electricidad y telecomunicaciones</small></div></div></section><section class="stats"><div class="wrap"><div class="stat"><strong>4</strong><span>áreas de servicio técnico</span></div><div class="stat"><strong>B2B</strong><span>atención institucional y corporativa</span></div><div class="stat"><strong>Potosí</strong><span>cobertura regional</span></div></div></section><section class="section"><div class="wrap"><div class="rowtitle">${title('Servicios','Soluciones técnicas para infraestructura crítica','Cuatro áreas de especialización integradas para responder a proyectos exigentes.')}${a('/servicios','Ver todos los servicios','btn alt')}</div>${serviceCards()}</div></section><section class="section" style="background:white"><div class="wrap"><div class="rowtitle">${title('Proyectos','Experiencia que se demuestra en campo','Así se organiza la presentación de los proyectos y servicios de la consultora.')}${a('/proyectos','Ver proyectos','btn alt')}</div>${note}${projectCards()}</div></section><section class="section dark"><div class="wrap two">${title('Nosotros','Una consultora orientada a la ejecución responsable','ILUTEX L.S. integra experiencia, criterio técnico y atención directa.') }<div class="feature" style="background:#ffffff12"><h3 style="color:white">Planificación, seguridad y responsabilidad técnica</h3><p>${a('/nosotros','Conocer ILUTEX L.S.')}</p></div></div></section>${cta()}`,
'/nosotros':()=>`${page('Nosotros','Experiencia técnica, compromiso y cercanía','Conoce el enfoque de la Consultora ILUTEX L.S.')}<section class="section"><div class="wrap two"><div>${title('Nuestra historia','Ingeniería al servicio de proyectos que conectan y transforman')}<p>ILUTEX L.S. desarrolla soluciones en electricidad y telecomunicaciones para clientes institucionales. Según la entrevista incluida en el proyecto de grado, su trayectoria se inicia en 2007.</p><p>Desde Potosí, su trabajo se orienta a proyectos que demandan coordinación, precisión y seguridad.</p></div><img src="${img[1]}" onerror="this.onerror=null;this.src='assets/montaje-antenas.svg'" alt="Fotografía de una torre de telecomunicaciones"></div></section><section class="section" style="background:white"><div class="wrap"><div class="grid three">${[['Misión','Brindar soluciones técnicas confiables para responder a las necesidades de cada proyecto.'],['Visión','Ser un referente regional en electricidad y telecomunicaciones.'],['Enfoque','Combinar planificación, seguridad y ejecución responsable.']].map(([a,b])=>`<article class="feature">${title('',a,b)}</article>`).join('')}</div></div></section>${cta()}`,
'/servicios':()=>`${page('Servicios','Capacidad técnica para proyectos exigentes','Soluciones en electricidad y telecomunicaciones con planificación y responsabilidad.')}<section class="section"><div class="wrap">${serviceCards()}</div></section><section class="section" style="background:white"><div class="wrap">${title('Proceso de trabajo','Un recorrido claro, de principio a fin')}<div class="grid" style="margin-top:35px">${['Diagnóstico','Propuesta','Ejecución','Entrega'].map((t,i)=>`<div class="feature"><span class="eyebrow">0${i+1}</span><h3>${t}</h3><p>${['Analizar el contexto y los requerimientos.','Definir el alcance del trabajo.','Coordinar el trabajo técnico.','Verificar el cumplimiento del alcance.'][i]}</p></div>`).join('')}</div></div></section>${cta()}`,
'/proyectos':()=>`${page('Proyectos realizados','Nuestra experiencia, visible en cada resultado','Una estructura de portafolio organizada por sector.') }<section class="section"><div class="wrap">${note}<div class="filter" id="filters">${['Todos','Eléctrico','Telecomunicaciones','Radio bases'].map((f,i)=>`<button class="${i===0?'active':''}" data-filter="${f}" aria-pressed="${i===0}">${f}</button>`).join('')}</div><div id="project-results">${projectCards()}</div></div></section>${cta()}`,
'/contacto':()=>`${page('Contacto','Conversemos sobre tu proyecto','Escríbenos mediante el formulario para registrar tu requerimiento.') }<section class="section"><div class="wrap two"><aside class="contact-panel"><h2>Información de contacto</h2><p><strong>Ubicación</strong><br>Potosí, Bolivia</p><p><strong>Teléfono y WhatsApp</strong><br>${contact.whatsapp?`<a href="https://wa.me/${contact.whatsapp}" target="_blank" rel="noopener noreferrer">${contact.whatsapp}</a>`:'Pendiente de confirmación'}</p>${contact.email?`<p><strong>Correo</strong><br><a href="mailto:${contact.email}">${contact.email}</a></p>`:''}${contact.hours?`<p><strong>Horario</strong><br>${contact.hours}</p>`:''}<p class="note" style="color:#ffffffbb">Los contactos oficiales deben validarse con la empresa antes de su publicación.</p></aside>${form('contacto')}</div></section>`,
'/cotizacion':()=>`${page('Solicitud de cotización','Cuéntanos qué necesitas','Completa los datos del proyecto. Puedes enviar la solicitud desde el navegador.') }<section class="section"><div class="wrap" style="max-width:1000px">${form('cotizacion')}</div></section>`,
'/confirmacion':()=>`<div class="confirmation"><div class="check">✓</div><span class="eyebrow">Solicitud registrada</span><h1>Gracias por contactar a ILUTEX L.S.</h1><p>Tu solicitud se registró y el servidor de correo confirmó que aceptó el mensaje para su entrega. ILUTEX podrá responderte a los datos facilitados.</p><div class="actions" style="justify-content:center">${a('/','Volver al inicio')}</div></div>`};
function form(kind){let quote=kind==='cotizacion';return `<form class="form" data-form="${kind}"><h2>${quote?'Datos del proyecto':'Envíanos un mensaje'}</h2><p>Los campos con * son obligatorios.</p><div class="formgrid"><label>Nombre completo *<input name="nombre" required maxlength="150" autocomplete="name"></label><label>Empresa o institución<input name="empresa" maxlength="150" autocomplete="organization"></label><label>Correo electrónico *<input name="correo" type="email" required maxlength="254" autocomplete="email"></label><label>Teléfono *<input name="telefono" type="tel" required minlength="6" maxlength="25" autocomplete="tel"></label><label class="full">Servicio de interés *<select name="servicio" required><option value="">Selecciona una opción</option>${services.map(s=>`<option>${s.name}</option>`).join('')}</select></label>${quote?'<label class="full">Ubicación del proyecto *<input name="ubicacion" required maxlength="250"></label>':''}<label class="full">${quote?'Describe la necesidad *':'Mensaje *'}<textarea name="${quote?'necesidad':'mensaje'}" required maxlength="3000"></textarea></label>${quote?'<label class="full">Rango de inversión estimado<select name="inversion"><option value="">Prefiero conversarlo con un asesor</option><option>Por definir</option><option>Ya existe un presupuesto de referencia</option></select></label>':''}</div><label class="checkbox"><input type="checkbox" name="acepta" required> Acepto el uso de mis datos para responder a esta solicitud. *</label><div class="error" role="alert" hidden></div><div class="actions"><button class="btn" type="submit">${quote?'Enviar solicitud':'Enviar mensaje'} ↗</button>${quote?a('/','Cancelar','btn alt'):''}</div><p class="note">El envío por correo requiere iniciar el servidor y configurar una cuenta SMTP. Tus datos se usarán únicamente para gestionar el contacto o cotización.</p></form>`}
function fallback(path){let segments=path.split('/').filter(Boolean);if(segments[0]==='servicio'){let s=services.find(x=>x.id===segments[1]);if(!s)return views['/servicios']();return `${page('Servicios / Detalle',s.name,s.detail)}<section class="section"><div class="wrap two"><img src="${serviceImages[services.indexOf(s)]}" alt="Imagen ilustrativa del servicio"><div>${title('Alcance','Ejecución técnica con seguridad y control')}<p>${s.detail}</p><ul>${s.points.map(q=>`<li>${q}</li>`).join('')}</ul><div class="actions">${a('/cotizacion','Cotizar este servicio')}</div></div></div></section>${cta()}`};if(segments[0]==='proyecto'){let p=projects.find(x=>x.id===segments[1]);if(!p)return views['/proyectos']();return `${page('Proyectos / '+p.cat,p.title,p.place)}<section class="section"><div class="wrap">${note}<img src="${p.pic}" onerror="this.onerror=null;this.src='assets/infraestructura-electrica.svg'" alt="Imagen ilustrativa de ${p.title}" style="width:100%;max-height:480px;object-fit:cover;border-radius:15px"><div class="details"><div><small>Sector</small><p>${p.cat}</p></div><div><small>Ubicación ilustrativa</small><p>${p.place}</p></div><div><small>Estado</small><p>Ficha de demostración</p></div></div><div class="grid three">${[['El reto','Presentar con claridad los requerimientos técnicos de un proyecto real.'],['La solución','Documentar procesos, fotografías autorizadas y alcance del trabajo.'],['El resultado','Completar la ficha con evidencias verificadas por la empresa.']].map(([a,b])=>`<article class="feature"><h3>${a}</h3><p>${b}</p></article>`).join('')}</div><div class="actions">${a('/contacto','Solicitar información')}</div></div></section>`}
return `<section class="section"><div class="wrap"><h1>Página no encontrada</h1><p>La sección que buscas no existe.</p>${a('/','Volver al inicio')}</div></section>`}
function render(){let path;try{path=decodeURI(rutaActual()).replace(/\/$/,'')||'/'}catch{path='/'}main.innerHTML=views[path]?views[path]():fallback(path);document.title=(path==='/'?'Inicio':(path.split('/')[1]||'Inicio').replace(/^./,s=>s.toUpperCase()))+' | ILUTEX L.S.';document.querySelectorAll('nav a').forEach(e=>e.classList.toggle('active',e.getAttribute('href')===(modoSinServidor?'#'+path:path)));document.getElementById('nav').classList.remove('open');document.getElementById('menu').setAttribute('aria-expanded','false');window.scrollTo(0,0);activarRevelado()}
function activarRevelado(){if(!('IntersectionObserver' in window)||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const nodes=main.querySelectorAll('.card,.rowtitle,.feature,.two>img,.hero>div,.stat,.form,.contact-panel');nodes.forEach((node,i)=>{node.classList.add('reveal');node.style.setProperty('--reveal-delay',Math.min(i%4*75,225)+'ms')});const observer=new IntersectionObserver((entries)=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}})},{threshold:.08,rootMargin:'0px 0px 40px 0px'});nodes.forEach(node=>observer.observe(node))}
document.addEventListener('click',event=>{const link=event.target.closest('a[data-route]');if(link){event.preventDefault();cambiarRuta(link.getAttribute('href').replace(/^#/,''));return}const filter=event.target.closest('[data-filter]');if(filter){document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===filter);x.setAttribute('aria-pressed',String(x===filter))});document.getElementById('project-results').innerHTML=projectCards(filter.dataset.filter==='Todos'?projects:projects.filter(x=>x.cat===filter.dataset.filter))}});
document.addEventListener('submit',async event=>{const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();const button=form.querySelector('[type=submit]');const box=form.querySelector('[role=alert]');box.hidden=true;button.disabled=true;button.textContent='Enviando...';try{const data=Object.fromEntries(new FormData(form));data.tipo=form.dataset.form;delete data.acepta;if (modoSinServidor) { throw Error('Para enviar tu solicitud por correo, abre la página mediante INICIAR_WINDOWS.bat. Abrir el HTML directamente no permite realizar envíos automáticos.'); }
else { const res=await fetch('/api/solicitudes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await res.json();if(!res.ok)throw Error(result.error||'No fue posible enviar la solicitud por correo.');cambiarRuta('/confirmacion'); }}catch(err){box.textContent=err.message||'Error de conexión';box.hidden=false}finally{button.disabled=false;button.textContent=form.dataset.form==='contacto'?'Enviar mensaje ↗':'Enviar solicitud ↗'}});
if(contact.email||contact.whatsapp){document.getElementById('footer-contact').textContent=[contact.email,contact.whatsapp].filter(Boolean).join(' · ')}
document.getElementById('menu').addEventListener('click',()=>{const nav=document.getElementById('nav');let open=nav.classList.toggle('open');document.getElementById('menu').setAttribute('aria-expanded',String(open))});window.addEventListener('popstate',render);window.addEventListener('hashchange',()=>{if(modoSinServidor)render()});render();
